const pagePermissions={dashboard:'DASHBOARD_VIEW',pos:'SALE_CREATE',sales:'SALE_VIEW_ALL',tickets:'QR_REDEEM',bars:['QR_REDEEM','REPLENISHMENT_REQUEST'],warehouse:'WAREHOUSE_MANAGE',stock:['STOCK_VIEW_ALL','STOCK_ADJUST'],restock:['REPLENISHMENT_REQUEST','REPLENISHMENT_MANAGE'],products:'PRODUCT_MANAGE',users:'USER_MANAGE_ADMIN'};
