function mobileNav(){const items=[['dashboard','Inicio'],['pos','Caja'],['tickets','Tickets'],['bars','Barras'],['stock','Stock']];return `<nav class="mobile-bar">${items.filter(([key])=>canAccessPage(key)).map(([key,label])=>`<button data-page="${key}" class="${page===key?'active':''}">${ico(key==='tickets'?'ticket':key)}<span>${label}</span></button>`).join('')}</nav>`}
function wireNav(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page))}
function go(p){if(!canAccessPage(p)){toast('No tenés permiso para acceder a esta sección');return}page=p;render()}
function pageHead(title,sub,actions=''){return `<div class="page-title"><div><h1>${title}</h1><p>${sub}</p></div><div class="title-actions">${actions}</div></div>`}
function dashboard(){const total=db.sales.reduce((a,s)=>a+s.total,0),del=delivered().length,pend=pending().length,avg=db.sales.length?total/db.sales.length:0;let cash=db.sales.flatMap(s=>s.items).filter(i=>i.method==='Efectivo').reduce((a,i)=>a+i.price*i.qty,0),qr=db.sales.flatMap(s=>s.items).filter(i=>i.method==='QR').reduce((a,i)=>a+i.price*i.qty,0);const units=db.sales.reduce((a,s)=>a+s.items.reduce((x,i)=>x+i.qty,0),0);const chartVals=[20,30,25,42,35,58,46,72,61,84,69,100];const points=chartVals.map((v,i)=>`${i*9.09},${112-v}`).join(' ');const popular=db.products.map(p=>({p,units:db.sales.flatMap(s=>s.items).filter(i=>i.id===p.id).reduce((a,i)=>a+i.qty,0)})).sort((a,b)=>b.units-a.units).slice(0,4);return `${pageHead('Dashboard', 'Resumen operativo de la noche · Datos de esta jornada',`<button class="btn">${ico('calendar')} Hoy⌄</button><button class="btn primary" data-page="pos">${ico('plus')} Nueva venta</button>`)}<section class="stats"><div class="stat"><div class="stat-top">Ventas totales<span class="stat-icon">${ico('sales')}</span></div><div class="stat-value">${currency(total)}</div><div class="stat-meta"><span class="positive">${db.sales.length} ventas</span> · esta jornada</div></div><div class="stat"><div class="stat-top">Tickets emitidos<span class="stat-icon">${ico('ticket')}</span></div><div class="stat-value">${db.tickets.length}</div><div class="stat-meta"><span class="positive">${del} entregados</span> · ${pend} pendientes</div></div><div class="stat"><div class="stat-top">Ticket promedio<span class="stat-icon">${ico('report')}</span></div><div class="stat-value">${currency(avg)}</div><div class="stat-meta">Por venta confirmada</div></div><div class="stat"><div class="stat-top">Productos vendidos<span class="stat-icon">${ico('box')}</span></div><div class="stat-value">${units}</div><div class="stat-meta">Unidades · esta jornada</div></div></section><div class="chart-grid"><section class="card"><div class="card-head"><div><h3>Ventas en el tiempo</h3><p>Actividad de venta durante la jornada</p></div><select class="select-small"><option>Por hora</option></select></div><div class="chart"><svg viewBox="0 0 100 120" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#e93e91" stop-opacity=".24"/><stop offset="1" stop-color="#e93e91" stop-opacity="0"/></linearGradient></defs><path d="M0,112 L${points} L100,120 L0,120Z" fill="url(#area)"/><polyline points="${points}" fill="none" stroke="#ed4c9a" stroke-width="1.6" vector-effect="non-scaling-stroke"/>${[25,55,85,115].map(y=>`<line class="gridline" x1="0" x2="100" y1="${y}" y2="${y}"/>`).join('')}</svg></div><div class="chart-labels"><span>22:00</span><span>23:00</span><span>00:00</span><span>01:00</span><span>02:00</span><span>03:00</span></div></section><section class="card"><div class="card-head"><div><h3>Ventas por medio de pago</h3><p>Distribución de cobros</p></div><button class="icon-btn" aria-label="Más">···</button></div><div class="donut-wrap"><div class="donut" style="background:conic-gradient(var(--pink) 0 ${total?cash/total*100:0}%,#8d76e5 ${total?cash/total*100:0}% ${total?(cash+qr)/total*100:0}%,#323039 ${total?(cash+qr)/total*100:0}% 100%)"><div class="donut-center"><strong>${currency(total)}</strong><small>Total vendido</small></div></div><div class="legend-list"><div><i class="dot" style="background:var(--pink)"></i>Efectivo<b>${currency(cash)}</b></div><div><i class="dot" style="background:#8e78e6"></i>QR<b>${currency(qr)}</b></div></div></div></section></div><div class="bottom-grid"><section class="card"><div class="card-head"><div><h3>Ventas recientes</h3><p>Últimas operaciones registradas</p></div><button class="btn" data-page="sales">Ver todas ${ico('arrow',13)}</button></div><div style="overflow:auto"><table class="table"><thead><tr><th>Venta</th><th>Hora</th><th>Cajero</th><th class="hide-mobile">Productos</th><th>Total</th><th>Ticket</th></tr></thead><tbody>${db.sales.length?db.sales.slice(-5).reverse().map(s=>`<tr><td>#${s.id}</td><td>${new Date(s.at).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})}</td><td>${escapeHtml(displayOperator(s.cashier))}</td><td class="hide-mobile">${s.items.reduce((a,i)=>a+i.qty,0)} productos</td><td>${currency(s.total)}</td><td><span class="badge ${s.ticket.status==='ENTREGADO'?'delivered':'pending'}">${s.ticket.status==='ENTREGADO'?'Entregado':'Pendiente'}</span></td></tr>`).join(''):`<tr><td colspan="6" class="empty-state">Las ventas confirmadas aparecerán aquí.</td></tr>`}</tbody></table></div></section><section class="card"><div class="card-head"><div><h3>Productos más vendidos</h3><p>Unidades vendidas en la jornada</p></div><button class="btn" data-page="sales">Ver ventas</button></div><div class="stock-list">${popular.map(({p,units:n})=>{const pct=units?Math.max(3,n/units*100):0;return `<div class="stock-line" style="grid-template-columns:100px 1fr 40px"><span class="label">${escapeHtml(p.name)}</span><div class="bar"><span style="width:${pct}%"></span></div><strong>${n}</strong></div>`}).join('')}</div><div style="border-top:1px solid var(--line);margin-top:18px;padding-top:13px;display:flex;justify-content:space-between;font-size:10px"><span class="muted">En depósito central</span><strong>${Object.values(db.stock).reduce((a,x)=>a+(x['Depósito Central']||0),0)} unidades</strong></div></section></div>`}
function posPage(){const cats=['Todos',...new Set(db.products.filter(p=>p.active!==false).map(p=>p.cat))],ps=db.products.filter(p=>p.active!==false&&(category==='Todos'||p.cat===category));return `${pageHead('Caja / Punto de venta','Seleccioná los productos para agregar a la venta',`<span class="role-tag">CAJA 01 · TURNO NOCHE</span>`)}<div class="pos-layout"><section><div class="category-row">${cats.map(c=>`<button class="category ${category===c?'active':''}" data-cat="${escapeHtml(c)}">${escapeHtml(c)}</button>`).join('')}</div><div class="product-grid">${ps.map(p=>`<button class="product-card" data-product="${escapeHtml(p.id)}"><div class="product-emoji">${p.emoji||'📦'}</div><strong>${escapeHtml(p.name)}</strong><small>${escapeHtml(p.cat)}</small><span class="add">+</span></button>`).join('')}</div></section><aside class="checkout"><section class="card"><div class="checkout-head"><h3>Venta actual</h3><button id="clear-cart">Limpiar</button></div><p class="cashier-note">${escapeHtml(identityName())} · Caja 01</p><div class="pay-switch"><button data-method="Efectivo" class="${predominant==='Efectivo'?'active':''}">💵 Efectivo</button><button data-method="QR" class="${predominant==='QR'?'active':''}">▦ QR</button></div><div class="cart-items">${cart.length?cart.map((i,n)=>`<div class="cart-item"><div><div class="cart-name">${i.product.emoji} ${escapeHtml(i.product.name)}</div><div class="cart-detail"><select class="item-method" data-index="${n}" aria-label="Medio de pago"><option ${i.method==='Efectivo'?'selected':''}>Efectivo</option><option ${i.method==='QR'?'selected':''}>QR</option></select> · ${currency(i.price)} c/u</div></div><div class="cart-actions"><button class="qty-btn" data-qty="${n}" data-delta="-1">−</button><span class="qty-val">${i.qty}</span><button class="qty-btn" data-qty="${n}" data-delta="1">+</button><button class="qty-btn" data-remove="${n}">×</button></div><div class="cart-detail" style="grid-column:1/-1;text-align:right">${currency(i.qty*i.price)}</div></div>`).join(''):`<div class="empty">Todavía no hay productos.<br>Elegí un producto para comenzar.</div>`}</div><div class="cart-total"><div class="total-row"><span>Subtotal</span><strong>${currency(cart.reduce((a,i)=>a+i.qty*i.price,0))}</strong></div><div class="total-row big"><span>Total</span><strong>${currency(cart.reduce((a,i)=>a+i.qty*i.price,0))}</strong></div></div><button class="btn primary confirm-btn" id="confirm-sale" ${cart.length?'':'disabled'}>${ico('check')} Confirmar venta</button><p class="pos-hint">Al confirmar se genera un ticket QR pendiente de entrega.</p></section></aside></div>`}
function openAdd(id){modalProduct=db.products.find(p=>p.id===id);modalQty=1;showAddModal()}
function showAddModal(){const p=modalProduct;showModal(`<button class="modal-close" data-close>×</button><h2>Agregar producto</h2><p class="sub">Elegí el precio y la cantidad para esta venta.</p><div class="modal-product"><div><strong>${p.emoji||'📦'} ${escapeHtml(p.name)}</strong><small>${escapeHtml(p.cat)}</small></div></div><div class="quantity-row"><label>Cantidad</label><div class="stepper"><button id="modal-minus">−</button><strong>${modalQty}</strong><button id="modal-plus">+</button></div></div><div class="price-choice"><button class="price-option" data-add-method="Efectivo"><small>💵 Precio efectivo</small><strong>${currency(p.cash)}</strong></button><button class="price-option" data-add-method="QR"><small>▦ Precio electrónico</small><strong>${currency(p.qr)}</strong></button></div><div class="modal-footer"><button class="btn" data-close>Cancelar</button></div>`);document.getElementById('modal-minus').onclick=()=>{modalQty=Math.max(1,modalQty-1);showAddModal()};document.getElementById('modal-plus').onclick=()=>{modalQty++;showAddModal()};document.querySelectorAll('[data-add-method]').forEach(b=>b.onclick=()=>{const method=b.dataset.addMethod;cart.push({product:p,method,price:method==='QR'?p.qr:p.cash,qty:modalQty});closeModal();render()})}
function saleConfirm(){if(!cart.length)return;for(const item of cart){const available=locations.slice(1).reduce((a,l)=>a+(db.stock[item.product.id]?.[l]||0),0);if(available<item.qty){toast(`Stock insuficiente de ${item.product.name} en las barras`);return}}const now=new Date(),saleId=++db.sequence,ticket={id:`YB-${now.getFullYear().toString().slice(2)}-${String(saleId).padStart(6,'0')}`,saleId,status:'PENDIENTE DE ENTREGA',at:now.toISOString(),items:cart.map(i=>({id:i.product.id,name:i.product.name,emoji:i.product.emoji,qty:i.qty,price:i.price,method:i.method})),total:cart.reduce((a,i)=>a+i.qty*i.price,0),cashier:identityName(),register:'Caja 01',bar:null};const sale={id:saleId,at:now.toISOString(),cashier:identityName(),register:'Caja 01',items:ticket.items.map(i=>({...i})),total:ticket.total,ticket};db.sales.push(sale);db.tickets.push(ticket);save();cart=[];showTicket(ticket);render()}
function showTicket(ticket){showModal(`<button class="modal-close" data-close>×</button><div class="ticket-modal"><div style="color:var(--mint)">${ico('check',29)}</div><h2>Venta confirmada</h2><div class="ticket-number">${ticket.id}</div><p class="sub">Escaneá este código en cualquiera de las barras.</p><div class="qr-shell"><canvas id="qr-canvas" width="174" height="174"></canvas></div><div class="ticket-status">⏳ PENDIENTE DE ENTREGA</div><div class="ticket-lines">${ticket.items.map(i=>`<div>${i.qty} × ${escapeHtml(i.name)}</div>`).join('')}</div><div class="ticket-total">${currency(ticket.total)}</div><div class="modal-footer" style="justify-content:center"><button class="btn" id="download-ticket">Descargar ticket</button><button class="btn primary" data-close>Listo</button></div></div>`);drawQR(ticket.id);document.getElementById('download-ticket').onclick=()=>downloadTicket(ticket)}
function hashText(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function drawQR(value){const canvas=document.getElementById('qr-canvas');if(!canvas)return;const ctx=canvas.getContext('2d'),size=29,cell=6,offset=(174-size*cell)/2;ctx.fillStyle='#fff';ctx.fillRect(0,0,174,174);let seedVal=hashText(value);const rand=()=>{seedVal=(seedVal*1664525+1013904223)>>>0;return seedVal>>>31};const finder=(ox,oy)=>{ctx.fillStyle='#16131b';ctx.fillRect(offset+ox*cell,offset+oy*cell,7*cell,7*cell);ctx.fillStyle='#fff';ctx.fillRect(offset+(ox+1)*cell,offset+(oy+1)*cell,5*cell,5*cell);ctx.fillStyle='#16131b';ctx.fillRect(offset+(ox+2)*cell,offset+(oy+2)*cell,3*cell,3*cell)};for(let y=0;y<size;y++)for(let x=0;x<size;x++){const finderArea=(x<8&&y<8)||(x>20&&y<8)||(x<8&&y>20);if(!finderArea&&rand()){ctx.fillStyle='#16131b';ctx.fillRect(offset+x*cell,offset+y*cell,cell,cell)}}finder(0,0);finder(22,0);finder(0,22);ctx.fillStyle='#16131b';ctx.font='bold 7px monospace';ctx.textAlign='center';ctx.fillText(value,87,172)}
function downloadTicket(ticket){const c=document.createElement('canvas');c.width=380;c.height=520;const x=c.getContext('2d');x.fillStyle='#100f14';x.fillRect(0,0,c.width,c.height);x.fillStyle='#f7f4fa';x.textAlign='center';x.font='bold 24px sans-serif';x.fillText('YambApp',190,40);x.font='bold 20px sans-serif';x.fillText(ticket.id,190,76);x.fillStyle='#ffca72';x.font='bold 12px sans-serif';x.fillText('PENDIENTE DE ENTREGA',190,100);const qr=document.getElementById('qr-canvas');if(qr)x.drawImage(qr,103,116,174,174);x.fillStyle='#f7f4fa';x.font='13px sans-serif';ticket.items.forEach((i,n)=>x.fillText(`${i.qty} × ${i.name} · ${currency(i.price*i.qty)}`,190,320+n*24));x.font='bold 18px sans-serif';x.fillText(`TOTAL ${currency(ticket.total)}`,190,405);x.font='11px sans-serif';x.fillStyle='#aaa5b0';x.fillText('Válido para retirar en cualquiera de las barras',190,454);const a=document.createElement('a');a.href=c.toDataURL('image/png');a.download=`ticket-${ticket.id}.png`;a.click()}
function salesPage(){const total=db.sales.reduce((a,s)=>a+s.total,0);return `${pageHead('Ventas','Historial de operaciones confirmadas',`<button class="btn" id="export-sales">${ico('report')} Exportar</button>`)}<section class="stats"><div class="stat"><div class="stat-top">Ventas registradas<span class="stat-icon">${ico('sales')}</span></div><div class="stat-value">${db.sales.length}</div><div class="stat-meta">Esta jornada</div></div><div class="stat"><div class="stat-top">Total vendido<span class="stat-icon">${ico('report')}</span></div><div class="stat-value">${currency(total)}</div><div class="stat-meta">Todas las cajas</div></div><div class="stat"><div class="stat-top">Efectivo<span class="stat-icon">💵</span></div><div class="stat-value">${currency(db.sales.flatMap(s=>s.items).filter(i=>i.method==='Efectivo').reduce((a,i)=>a+i.qty*i.price,0))}</div><div class="stat-meta">Cobros en efectivo</div></div><div class="stat"><div class="stat-top">QR<span class="stat-icon">▦</span></div><div class="stat-value">${currency(db.sales.flatMap(s=>s.items).filter(i=>i.method==='QR').reduce((a,i)=>a+i.qty*i.price,0))}</div><div class="stat-meta">Cobros electrónicos</div></div></section><section class="card"><div class="card-head"><div><h3>Operaciones</h3><p>${db.sales.length} ventas registradas</p></div><div class="filter-row"><label class="search">${ico('search',15)}<input id="sales-search" placeholder="Buscar venta o ticket…"></label><select class="select-small" id="sale-filter"><option value="Todas">Todos los estados</option><option>PENDIENTE DE ENTREGA</option><option>ENTREGADO</option></select></div></div><div style="overflow:auto"><table class="table"><thead><tr><th>N° venta</th><th>Fecha y hora</th><th>Cajero</th><th>Caja</th><th>Productos</th><th>Total</th><th>Ticket</th></tr></thead><tbody id="sales-body">${salesRows(db.sales)}</tbody></table></div></section>`}
function salesRows(list){return list.length?list.slice().reverse().map(s=>`<tr class="ticket-row" data-ticket="${s.ticket.id}"><td>#${s.id}</td><td>${fmtDate(new Date(s.at))}</td><td>${escapeHtml(displayOperator(s.cashier))}</td><td>${escapeHtml(s.register)}</td><td>${s.items.reduce((a,i)=>a+i.qty,0)} un.</td><td>${currency(s.total)}</td><td><span class="badge ${s.ticket.status==='ENTREGADO'?'delivered':'pending'}">${s.ticket.status==='ENTREGADO'?'Entregado':'Pendiente'}</span></td></tr>`).join(''):`<tr><td colspan="7" class="empty-state">No se encontraron ventas.</td></tr>`}
function bindSales(){const filter=()=>{const q=(document.getElementById('sales-search')?.value||'').toLowerCase(),st=document.getElementById('sale-filter')?.value||'Todas';const list=db.sales.filter(s=>(st==='Todas'||s.ticket.status===st)&&(!q||String(s.id).includes(q)||s.ticket.id.toLowerCase().includes(q)||s.cashier.toLowerCase().includes(q)));document.getElementById('sales-body').innerHTML=salesRows(list);document.querySelectorAll('[data-ticket]').forEach(r=>r.onclick=()=>showTicketDetail(r.dataset.ticket))};document.getElementById('sales-search').oninput=filter;document.getElementById('sale-filter').onchange=filter;document.querySelectorAll('[data-ticket]').forEach(r=>r.onclick=()=>showTicketDetail(r.dataset.ticket));document.getElementById('export-sales').onclick=()=>{const rows=[['Venta','Fecha','Cajero','Caja','Productos','Total','Ticket'],...db.sales.map(s=>[s.id,s.at,s.cashier,s.register,s.items.map(i=>`${i.qty}x ${i.name} (${i.method})`).join(' / '),s.total,s.ticket.id])];const csv=rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));a.download='yambapp-ventas.csv';a.click();URL.revokeObjectURL(a.href)}}
function showTicketDetail(id){const t=db.tickets.find(x=>x.id===id);if(!t)return;showModal(`<button class="modal-close" data-close>×</button><h2>Ticket ${escapeHtml(t.id)}</h2><p class="sub">Venta #${t.saleId} · ${fmtDate(new Date(t.at))} · ${escapeHtml(displayOperator(t.cashier))}</p>${t.status==='ENTREGADO'?`<div class="warning-box">TICKET YA ENTREGADO</div><div class="warning-detail">Retirado en <strong>${escapeHtml(t.bar)}</strong> por ${escapeHtml(t.deliveredBy)} · ${fmtDate(new Date(t.deliveredAt))}</div>`:`<div class="ticket-status">⏳ PENDIENTE DE ENTREGA</div>`}<div class="ticket-result">${t.items.map(i=>`<div class="ticket-item-line"><span>${i.qty} × ${escapeHtml(i.name)}</span><strong>${currency(i.qty*i.price)}</strong></div>`).join('')}<div class="ticket-total">Total ${currency(t.total)}</div></div><div class="modal-footer"><button class="btn" data-close>Cerrar</button></div>`)}
function ticketsPage(){return `${pageHead('Tickets QR','Consulta, escaneo y estado de tickets',`<button class="btn primary" id="open-scanner">${ico('camera')} Escanear ticket</button>`)}<section class="stats"><div class="stat"><div class="stat-top">Emitidos<span class="stat-icon">${ico('ticket')}</span></div><div class="stat-value">${db.tickets.length}</div><div class="stat-meta">Tickets generados</div></div><div class="stat"><div class="stat-top">Pendientes<span class="stat-icon">${ico('clock')}</span></div><div class="stat-value">${pending().length}</div><div class="stat-meta">Esperando retiro</div></div><div class="stat"><div class="stat-top">Entregados<span class="stat-icon">${ico('check')}</span></div><div class="stat-value">${delivered().length}</div><div class="stat-meta">Retirados en barra</div></div><div class="stat"><div class="stat-top">Tiempo promedio<span class="stat-icon">${ico('clock')}</span></div><div class="stat-value">—</div><div class="stat-meta">Entre venta y entrega</div></div></section><section class="card"><div class="card-head"><div><h3>Tickets recientes</h3><p>Seleccioná un ticket para ver su detalle</p></div></div><div style="overflow:auto"><table class="table"><thead><tr><th>Ticket</th><th>Hora</th><th>Venta</th><th>Productos</th><th>Total</th><th>Estado</th><th>Entrega</th></tr></thead><tbody>${db.tickets.length?db.tickets.slice().reverse().map(t=>`<tr class="ticket-row" data-ticket="${t.id}"><td>${t.id}</td><td>${new Date(t.at).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})}</td><td>#${t.saleId}</td><td>${t.items.reduce((a,i)=>a+i.qty,0)} un.</td><td>${currency(t.total)}</td><td><span class="badge ${t.status==='ENTREGADO'?'delivered':'pending'}">${t.status==='ENTREGADO'?'Entregado':'Pendiente'}</span></td><td>${t.bar||'—'}</td></tr>`).join(''):`<tr><td colspan="7" class="empty-state">Los tickets aparecerán al confirmar una venta.</td></tr>`}</tbody></table></div></section>`}
function openScanner(){scannerTicket=null;showScannerModal('')}
function showScannerModal(value){showModal(`<button class="modal-close" data-close>×</button><h2>Escanear ticket</h2><p class="sub">Escaneá el QR o ingresá el número del ticket.</p><div class="scanner-box">${ico('camera',34)}<strong>Lector de tickets</strong><small>Ingresá el código del ticket para simular el escaneo.</small><input class="scanner-input" id="scan-code" placeholder="Ej: YB-26-001048" value="${escapeHtml(value)}"></div><div id="scan-result"></div><div class="modal-footer"><button class="btn" data-close>Cerrar</button></div>`);const input=document.getElementById('scan-code');input.oninput=()=>findTicket(input.value);if(value)findTicket(value);input.focus()}
function findTicket(code){const t=db.tickets.find(x=>x.id.toLowerCase()===code.trim().toLowerCase()),host=document.getElementById('scan-result');if(!host)return;if(!code.trim()){host.innerHTML='';return}if(!t){host.innerHTML=`<div class="ticket-result"><div class="warning-box" style="background:#382c19;color:var(--yellow)">TICKET NO ENCONTRADO</div><div class="warning-detail">Verificá el código e intentá nuevamente.</div></div>`;return}scannerTicket=t;if(t.status==='ENTREGADO'){host.innerHTML=`<div class="ticket-result"><div class="warning-box">TICKET YA ENTREGADO</div><div class="warning-detail">Entregado en <strong>${escapeHtml(t.bar)}</strong> por ${escapeHtml(t.deliveredBy)}<br>${fmtDate(new Date(t.deliveredAt))}</div>${ticketItemLines(t)}</div>`;return}host.innerHTML=`<div class="ticket-result"><div class="result-head"><strong>${escapeHtml(t.id)}</strong><span class="badge pending">Pendiente</span></div><div class="warning-detail">Venta #${t.saleId} · ${escapeHtml(displayOperator(t.cashier))}</div>${ticketItemLines(t)}<div class="modal-field"><label>Barra que entrega</label><select id="deliver-bar">${locations.slice(1).map(l=>`<option>${l}</option>`).join('')}</select></div><button class="btn primary ticket-delivery" id="deliver-ticket">${ico('check')} Entregar pedido</button></div>`;document.getElementById('deliver-ticket').onclick=()=>deliverTicket(t.id,document.getElementById('deliver-bar').value)}
function ticketItemLines(t){return t.items.map(i=>`<div class="ticket-item-line"><span>${i.qty} × ${escapeHtml(i.name)}</span><strong>${currency(i.qty*i.price)}</strong></div>`).join('')}
function deliverTicket(id,bar){const t=db.tickets.find(x=>x.id===id);if(!t||t.status==='ENTREGADO'){findTicket(id);return}for(const item of t.items){const stock=db.stock[item.id]?.[bar]||0;if(stock<item.qty){toast(`Stock insuficiente en ${bar}: ${item.name}`);return}}const now=new Date();for(const item of t.items){db.stock[item.id][bar]-=item.qty;db.movements.push({id:`MOV-${Date.now()}-${item.id}`,product:item.id,qty:item.qty,from:bar,to:null,type:'Venta',user:identityName(),at:now.toISOString(),ticket:id})}t.status='ENTREGADO';t.bar=bar;t.deliveredBy=identityName();t.deliveredAt=now.toISOString();const sale=db.sales.find(s=>s.id===t.saleId);if(sale)sale.ticket=t;save();toast(`Pedido entregado en ${bar}`);showScannerModal(id);render()}
function barsPage(){const pend=pending();return `${pageHead('Barras','Entrega de pedidos y stock disponible',`<button class="btn primary" id="open-scanner">${ico('camera')} Escanear ticket</button>`)}<div class="simple-grid">${locations.slice(1).map((l,n)=>{const qty=Object.values(db.stock).reduce((a,x)=>a+(x[l]||0),0),due=pend.filter(t=>t.items.some(i=>(db.stock[i.id]?.[l]||0)<i.qty)).length;return `<section class="card"><div class="card-head"><div><h3>${l}</h3><p>${['Gin tonic · Fernet · Cerveza','Cerveza · Tragos','Tragos · Sin alcohol','Barra auxiliar'][n]}</p></div><span class="pulse"></span></div><div class="stat-value" style="font-size:23px">${qty} <span style="font:400 10px var(--font);color:var(--muted)">unidades</span></div><div class="stock-list" style="margin:14px 0">${db.products.slice(0,4).map(p=>`<div class="stock-line"><span class="label">${escapeHtml(p.name)}</span><div class="bar"><span style="width:${Math.min(100,(db.stock[p.id]?.[l]||0)*3)}%"></span></div><strong>${db.stock[p.id]?.[l]||0}</strong></div>`).join('')}</div><div style="border-top:1px solid var(--line);padding-top:12px;display:flex;justify-content:space-between;align-items:center"><span class="muted" style="font-size:10px">${due?`${due} con stock bajo`:'Operativa'}</span><button class="btn" data-restock-bar="${l}">Solicitar stock ${ico('arrow',13)}</button></div></section>`}).join('')}</div><section class="card section"><div class="card-head"><div><h3>Pedidos pendientes de retiro</h3><p>El cliente puede retirar en cualquier barra</p></div><button class="btn" id="open-scanner">${ico('camera')} Escanear</button></div><div style="overflow:auto"><table class="table"><thead><tr><th>Ticket</th><th>Hora</th><th>Productos</th><th>Total</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${pend.length?pend.slice().reverse().map(t=>`<tr><td>${t.id}</td><td>${new Date(t.at).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})}</td><td>${t.items.map(i=>`${i.qty} × ${escapeHtml(i.name)}`).join(', ')}</td><td>${currency(t.total)}</td><td><span class="badge pending">Pendiente</span></td><td><button class="btn" data-scan-ticket="${t.id}">Procesar ticket</button></td></tr>`).join(''):`<tr><td colspan="6" class="empty-state">No hay pedidos esperando retiro.</td></tr>`}</tbody></table></div></section>`}
function stockPage(){const grand=Object.values(db.stock).reduce((a,x)=>a+Object.values(x).reduce((n,v)=>n+v,0),0);return `${pageHead('Stock por ubicación','Inventario distribuido en depósito y barras',`<button class="btn" id="stock-adjust">${ico('plus')} Ajuste de stock</button>`)}<section class="stats"><div class="stat"><div class="stat-top">Stock total<span class="stat-icon">${ico('stock')}</span></div><div class="stat-value">${grand}</div><div class="stat-meta">Unidades en todas las ubicaciones</div></div>${locations.slice(0,3).map((l,i)=>{const amount=Object.values(db.stock).reduce((a,x)=>a+(x[l]||0),0);return `<div class="stat"><div class="stat-top">${l}<span class="stat-icon">${ico(i?'bars':'warehouse')}</span></div><div class="stat-value">${amount}</div><div class="stat-meta">Unidades disponibles</div></div>`}).join('')}</section><section class="card"><div class="card-head"><div><h3>Inventario por producto</h3><p>Existencias separadas por ubicación</p></div><label class="search">${ico('search',15)}<input id="stock-search" placeholder="Buscar producto…"></label></div><div style="overflow:auto"><table class="table"><thead><tr><th>Producto</th>${locations.map(l=>`<th>${l}</th>`).join('')}<th>Total</th></tr></thead><tbody id="stock-body">${stockRows(db.products)}</tbody></table></div></section><section class="card section"><div class="card-head"><div><h3>Movimientos recientes</h3><p>Registro de cambios de inventario</p></div></div>${movementList()}</section>`}
function stockRows(products){return products.map(p=>{const row=db.stock[p.id]||{};return `<tr><td><div class="product-cell"><span class="product-thumb">${p.emoji||'📦'}</span>${escapeHtml(p.name)}</div></td>${locations.map(l=>`<td>${row[l]||0}</td>`).join('')}<td><strong>${locations.reduce((a,l)=>a+(row[l]||0),0)}</strong></td></tr>`}).join('')||`<tr><td colspan="7" class="empty-state">No se encontraron productos.</td></tr>`}
function movementList(){return db.movements.length?`<div class="movements">${db.movements.slice().reverse().slice(0,8).map(m=>`<div class="movement"><span class="movement-ico">${ico(m.type==='Venta'?'check':'restock',14)}</span><div><strong>${escapeHtml(db.products.find(p=>p.id===m.product)?.name||m.product)} · ${escapeHtml(m.type)}</strong><small>${m.from?escapeHtml(m.from):'Carga'}${m.to?' → '+escapeHtml(m.to):''} · ${escapeHtml(displayOperator(m.user))} · ${fmtDate(new Date(m.at))}</small></div><span class="move-qty">−${m.qty}</span></div>`).join('')}</div>`:`<div class="empty-state">Los movimientos de stock quedarán registrados aquí.</div>`}
function openAdjustment(){showModal(`<button class="modal-close" data-close>×</button><h2>Ajuste de stock</h2><p class="sub">Registrá una carga o corrección de inventario.</p><div class="modal-field"><label>Producto</label><select id="adjust-product">${db.products.map(p=>`<option value="${p.id}">${escapeHtml(p.name)}</option>`).join('')}</select></div><div class="modal-field"><label>Ubicación</label><select id="adjust-location">${locations.map(l=>`<option>${l}</option>`).join('')}</select></div><div class="modal-field"><label>Tipo de movimiento</label><select id="adjust-type"><option>Carga inicial</option><option>Ajuste</option><option>Traslado</option></select></div><div class="modal-field"><label>Cantidad a sumar</label><input id="adjust-qty" type="number" min="1" value="1"></div><div class="modal-footer"><button class="btn" data-close>Cancelar</button><button class="btn primary" id="save-adjust">Guardar movimiento</button></div>`);document.getElementById('save-adjust').onclick=()=>{const product=document.getElementById('adjust-product').value,loc=document.getElementById('adjust-location').value,qty=Number(document.getElementById('adjust-qty').value),type=document.getElementById('adjust-type').value;if(!qty||qty<1){toast('Ingresá una cantidad válida');return}db.stock[product][loc]+=qty;db.movements.push({product,qty,from:null,to:loc,type,user:identityName(),at:new Date().toISOString()});save();closeModal();render();toast('Movimiento de stock registrado')}}
function productsPage(){return `${pageHead('Productos','Catálogo, precios y estado de venta',`<button class="btn primary" id="new-product">${ico('plus')} Nuevo producto</button>`)}<div class="filter-row" style="margin-bottom:15px"><label class="search">${ico('search',15)}<input id="product-search" placeholder="Buscar producto…"></label><select id="product-category" class="select-small"><option>Todos</option>${[...new Set(db.products.map(p=>p.cat))].map(c=>`<option>${escapeHtml(c)}</option>`).join('')}</select></div><div class="simple-grid" id="product-grid">${productCards(db.products)}</div>`}
function productCards(list){return list.map(p=>`<section class="product-admin"><div style="display:flex;justify-content:space-between"><span class="emoji">${p.emoji||'📦'}</span><span class="badge ${p.active===false?'cancel':'delivered'}">${p.active===false?'Inactivo':'Activo'}</span></div><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml(p.cat)}</p><div class="prices"><div><small>Efectivo</small><strong>${currency(p.cash)}</strong></div><div><small>Electrónico</small><strong>${currency(p.qr)}</strong></div></div><button class="btn" style="margin-top:12px;width:100%;justify-content:center" data-edit-product="${escapeHtml(p.id)}">Editar producto</button></section>`).join('')||`<div class="empty-state">No se encontraron productos.</div>`}
function bindProducts(){const f=()=>{const q=document.getElementById('product-search').value.toLowerCase(),c=document.getElementById('product-category').value;document.getElementById('product-grid').innerHTML=productCards(db.products.filter(p=>(c==='Todos'||p.cat===c)&&p.name.toLowerCase().includes(q)))};document.getElementById('product-search').oninput=f;document.getElementById('product-category').onchange=f;document.querySelectorAll('[data-edit-product]').forEach(b=>b.onclick=()=>productForm(b.dataset.editProduct));document.getElementById('new-product').onclick=()=>productForm(null)}
function productForm(id){const p=id?db.products.find(x=>x.id===id):{id:'',name:'',cat:'Tragos',cash:0,qr:0,emoji:'🍸',active:true};showModal(`<button class="modal-close" data-close>×</button><h2>${id?'Editar producto':'Nuevo producto'}</h2><p class="sub">Configurá el catálogo y los precios de venta.</p><div class="modal-field"><label>Nombre</label><input id="p-name" value="${escapeHtml(p.name)}"></div><div class="modal-field"><label>Categoría</label><input id="p-cat" value="${escapeHtml(p.cat)}" placeholder="Tragos, Cervezas…"></div><div class="modal-field"><label>Emoji</label><input id="p-emoji" value="${escapeHtml(p.emoji||'📦')}"></div><div class="modal-field"><label>Precio en efectivo</label><input id="p-cash" type="number" min="0" value="${p.cash}"></div><div class="modal-field"><label>Precio electrónico / QR</label><input id="p-qr" type="number" min="0" value="${p.qr}"></div><div class="modal-field"><label>Estado</label><select id="p-active"><option value="true" ${p.active!==false?'selected':''}>Activo</option><option value="false" ${p.active===false?'selected':''}>Inactivo</option></select></div><div class="modal-footer"><button class="btn" data-close>Cancelar</button><button class="btn primary" id="save-product">Guardar</button></div>`);document.getElementById('save-product').onclick=()=>{const name=document.getElementById('p-name').value.trim(),cat=document.getElementById('p-cat').value.trim(),cash=Number(document.getElementById('p-cash').value),qr=Number(document.getElementById('p-qr').value);if(!name||!cat||cash<0||qr<0){toast('Completá el nombre, categoría y precios');return}if(id){Object.assign(db.products.find(x=>x.id===id),{name,cat,cash,qr,emoji:document.getElementById('p-emoji').value,active:document.getElementById('p-active').value==='true'})}else{const key=name.toUpperCase().replace(/[^A-Z0-9]+/g,'_');if(db.products.some(x=>x.id===key)){toast('Ya existe un producto con ese nombre');return}db.products.push({id:key,name,cat,cash,qr,emoji:document.getElementById('p-emoji').value,active:document.getElementById('p-active').value==='true'});db.stock[key]=Object.fromEntries(locations.map(l=>[l,0]))}save();closeModal();render();toast(id?'Producto actualizado':'Producto creado')}}
function warehousePage(){const restocks=db.requests.filter(r=>r.status!=='RECIBIDA');return `${pageHead('Depósito central','Existencias y solicitudes de reposición',`<button class="btn" data-page="stock">${ico('stock')} Ver inventario</button>`)}<section class="stats"><div class="stat"><div class="stat-top">Productos<span class="stat-icon">${ico('box')}</span></div><div class="stat-value">${db.products.length}</div><div class="stat-meta">En catálogo</div></div><div class="stat"><div class="stat-top">Unidades disponibles<span class="stat-icon">${ico('warehouse')}</span></div><div class="stat-value">${Object.values(db.stock).reduce((a,x)=>a+(x['Depósito Central']||0),0)}</div><div class="stat-meta">En depósito central</div></div><div class="stat"><div class="stat-top">Solicitudes abiertas<span class="stat-icon">${ico('restock')}</span></div><div class="stat-value">${restocks.length}</div><div class="stat-meta">Pendientes de envío o recepción</div></div><div class="stat"><div class="stat-top">Movimientos<span class="stat-icon">${ico('report')}</span></div><div class="stat-value">${db.movements.length}</div><div class="stat-meta">Trazabilidad de inventario</div></div></section><section class="card"><div class="card-head"><div><h3>Stock en depósito</h3><p>Unidades disponibles para reposición</p></div></div><div style="overflow:auto"><table class="table"><thead><tr><th>Producto</th><th>Cantidad</th><th>Estado</th><th></th></tr></thead><tbody>${db.products.map(p=>`<tr><td><div class="product-cell"><span class="product-thumb">${p.emoji||'📦'}</span>${escapeHtml(p.name)}</div></td><td>${db.stock[p.id]?.['Depósito Central']||0}</td><td><span class="badge ${(db.stock[p.id]?.['Depósito Central']||0)>15?'delivered':'pending'}">${(db.stock[p.id]?.['Depósito Central']||0)>15?'Disponible':'Stock bajo'}</span></td><td></td></tr>`).join('')}</tbody></table></div></section><section class="card section"><div class="card-head"><div><h3>Reposiciones para preparar</h3><p>Prepará los pedidos para que cada barra confirme su recepción</p></div></div>${restocks.length?`<div style="overflow:auto"><table class="table"><thead><tr><th>Solicitud</th><th>Barra</th><th>Producto</th><th>Cantidad</th><th>Fecha</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${restocks.map(r=>`<tr><td>${r.id}</td><td>${r.bar}</td><td>${escapeHtml(db.products.find(p=>p.id===r.product)?.name||r.product)}</td><td>${r.qty}</td><td>${fmtDate(new Date(r.at))}</td><td><span class="badge ${r.status==='ENVIADA'?'pending':'cancel'}">${r.status}</span></td><td>${r.status==='SOLICITADA'?`<button class="btn" data-send="${r.id}">Marcar enviada</button>`:`<span class="muted">Esperando recepción</span>`}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state">No hay solicitudes pendientes de preparación.</div>`}</section>`}
function restockPage(){return `${pageHead('Reposiciones','Solicitudes desde barras y movimientos de depósito',`<button class="btn primary" id="new-restock">${ico('plus')} Nueva solicitud</button>`)}<div class="bottom-grid"><section class="card"><div class="card-head"><div><h3>Solicitudes</h3><p>Flujo de reposición entre ubicaciones</p></div></div>${db.requests.length?`<div style="overflow:auto"><table class="table"><thead><tr><th>N°</th><th>Barra</th><th>Producto</th><th>Cantidad</th><th>Solicitó</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${db.requests.slice().reverse().map(r=>`<tr><td>${r.id}</td><td>${r.bar}</td><td>${escapeHtml(db.products.find(p=>p.id===r.product)?.name||r.product)}</td><td>${r.qty}</td><td>${escapeHtml(displayOperator(r.user))}</td><td><span class="badge ${r.status==='RECIBIDA'?'delivered':r.status==='ENVIADA'?'pending':'cancel'}">${r.status}</span></td><td>${r.status==='SOLICITADA'?`<button class="btn" data-send="${r.id}">Marcar enviada</button>`:r.status==='ENVIADA'?`<button class="btn primary" data-receive="${r.id}">Confirmar recepción</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state">No hay solicitudes todavía.<br>Creá una reposición para iniciar el flujo.</div>`}</section><section class="card"><div class="card-head"><div><h3>Cómo funciona</h3><p>Movimiento trazable entre ubicaciones</p></div></div><div class="stock-list"><div class="movement"><span class="movement-ico">1</span><div><strong>Solicitud de barra</strong><small>Se registra barra, producto, cantidad y usuario.</small></div></div><div class="movement"><span class="movement-ico">2</span><div><strong>Preparación en depósito</strong><small>El depósito marca la reposición como enviada.</small></div></div><div class="movement"><span class="movement-ico">3</span><div><strong>Recepción confirmada</strong><small>Al recibir, se mueve el stock y se registra el historial.</small></div></div></div></section></div>`}
function newRestock(defaultBar='Barra 1'){showModal(`<button class="modal-close" data-close>×</button><h2>Solicitar reposición</h2><p class="sub">La solicitud quedará pendiente hasta que el depósito la prepare.</p><div class="modal-field"><label>Barra solicitante</label><select id="r-bar">${locations.slice(1).map(l=>`<option ${l===defaultBar?'selected':''}>${l}</option>`).join('')}</select></div><div class="modal-field"><label>Producto</label><select id="r-product">${db.products.map(p=>`<option value="${p.id}">${escapeHtml(p.name)} · ${db.stock[p.id]?.['Depósito Central']||0} en depósito</option>`).join('')}</select></div><div class="modal-field"><label>Cantidad</label><input id="r-qty" type="number" min="1" value="12"></div><div class="modal-footer"><button class="btn" data-close>Cancelar</button><button class="btn primary" id="save-restock">Crear solicitud</button></div>`);document.getElementById('save-restock').onclick=()=>{const bar=document.getElementById('r-bar').value,product=document.getElementById('r-product').value,qty=Number(document.getElementById('r-qty').value);if(!qty||qty<1){toast('Ingresá una cantidad válida');return}if(qty>(db.stock[product]?.['Depósito Central']||0)){toast('La solicitud supera el stock disponible del depósito');return}const r={id:`REP-${String(db.requests.length+1).padStart(4,'0')}`,bar,product,qty,status:'SOLICITADA',at:new Date().toISOString(),user:identityName()};db.requests.push(r);save();closeModal();render();toast('Solicitud enviada al depósito')}}
function advanceRequest(id,status){const r=db.requests.find(x=>x.id===id);if(!r)return;if(status==='ENVIADA'){r.status='ENVIADA';r.sentAt=new Date().toISOString()}else{const available=db.stock[r.product]?.['Depósito Central']||0;if(available<r.qty){toast('Stock insuficiente en depósito');return}db.stock[r.product]['Depósito Central']-=r.qty;db.stock[r.product][r.bar]=(db.stock[r.product][r.bar]||0)+r.qty;r.status='RECIBIDA';r.receivedAt=new Date().toISOString();db.movements.push({product:r.product,qty:r.qty,from:'Depósito Central',to:r.bar,type:'Reposición',user:identityName(),at:r.receivedAt})}save();render();toast(status==='ENVIADA'?'Reposición marcada como enviada':'Recepción confirmada · stock actualizado')}
function showModal(html){closeModal();const el=document.createElement('div');el.className='modal-backdrop';el.id='modal-root';el.innerHTML=`<div class="modal">${html}</div>`;el.addEventListener('click',e=>{if(e.target===el||e.target.closest('[data-close]'))closeModal()});document.body.appendChild(el);document.onkeydown=e=>{if(e.key==='Escape')closeModal()}}
function closeModal(){document.getElementById('modal-root')?.remove();document.onkeydown=null}
const userRoleLabels={ADMIN:'Administrador',ENCARGADO:'Encargado',CAJERO:'Cajero',BARRA:'Barra'};
function usersPage(){const admin=window.yambaAuth?.profile?.role==='ADMIN';if(!admin){page='dashboard';return dashboard()}const rows=usersCache.map(u=>`<tr><td>${escapeHtml(`${u.firstName} ${u.lastName}`)}</td><td>${escapeHtml(u.email)}</td><td>${escapeHtml(userRoleLabels[u.role]||u.role)}</td><td><span class="badge ${u.isActive?'success':'cancel'}">${u.isActive?'Activo':'Inactivo'}</span></td><td>${u.createdAt?new Intl.DateTimeFormat('es-AR',{dateStyle:'medium'}).format(new Date(u.createdAt)):'—'}</td><td><button class="btn" data-edit-user="${escapeHtml(u.id)}">Editar</button></td></tr>`).join('');return `${pageHead('Usuarios','Administrá los perfiles y el acceso al sistema.',`<button class="btn primary" id="invite-user">${ico('plus')} Invitar usuario</button>`)}<section class="card users-card">${usersError?`<div class="users-error">${escapeHtml(usersError)} <button class="btn" id="retry-users">Reintentar</button></div>`:''}<div style="overflow:auto"><table class="table users-table"><thead><tr><th>Nombre y apellido</th><th>Email</th><th>Rol</th><th>Estado</th><th>Creado</th><th>Acciones</th></tr></thead><tbody>${usersLoading?'<tr><td colspan="6" class="empty-state">Cargando usuarios…</td></tr>':rows||'<tr><td colspan="6" class="empty-state">No hay perfiles para mostrar.</td></tr>'}</tbody></table></div></section>`}
async function loadUsers(){if(page!=='users'||window.yambaAuth?.profile?.role!=='ADMIN'||usersLoading||usersLoaded)return;usersLoading=true;usersError='';render();try{const result=await window.yambaAuth.apiFetch('/api/admin/users');usersCache=result.users||[];usersLoaded=true}catch(error){usersError=error.message}finally{usersLoading=false;render()}}
function userForm(user=null){const edit=Boolean(user);showModal(`<button class="modal-close" data-close aria-label="Cerrar">×</button><h2>${edit?'Editar usuario':'Invitar usuario'}</h2><p class="sub">${edit?'Actualizá el perfil. Las contraseñas se administran desde Supabase Auth.':'La persona recibirá un email para establecer su contraseña.'}</p><form id="user-form"><div class="modal-field"><label for="user-first-name">Nombre</label><input id="user-first-name" name="firstName" maxlength="100" value="${escapeHtml(user?.firstName||'')}" required></div><div class="modal-field"><label for="user-last-name">Apellido</label><input id="user-last-name" name="lastName" maxlength="100" value="${escapeHtml(user?.lastName||'')}" required></div>${edit?`<div class="modal-field"><label>Email</label><input value="${escapeHtml(user.email)}" readonly></div>`:`<div class="modal-field"><label for="user-email">Email</label><input id="user-email" name="email" type="email" maxlength="254" required></div>`}<div class="modal-field"><label for="user-role">Rol</label><select id="user-role" name="role">${Object.entries(userRoleLabels).map(([code,label])=>`<option value="${code}" ${user?.role===code?'selected':''}>${label}</option>`).join('')}</select></div>${edit?`<div class="modal-field"><label for="user-active">Estado</label><select id="user-active" name="isActive"><option value="true" ${user.isActive?'selected':''}>Activo</option><option value="false" ${!user.isActive?'selected':''}>Inactivo</option></select></div>`:''}<div class="modal-footer"><button type="button" class="btn" data-close>Cancelar</button><button class="btn primary" type="submit">${edit?'Guardar cambios':'Enviar invitación'}</button></div></form>`);document.getElementById('user-form').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget),payload={firstName:String(form.get('firstName')).trim(),lastName:String(form.get('lastName')).trim(),role:String(form.get('role'))};try{if(edit){payload.isActive=form.get('isActive')==='true';await window.yambaAuth.apiFetch(`/api/admin/users/${encodeURIComponent(user.id)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)})}else{payload.email=String(form.get('email')).trim();await window.yambaAuth.apiFetch('/api/admin/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)})}closeModal();toast(edit?'Usuario actualizado':'Invitación enviada por email');usersCache=[];usersLoaded=false;await loadUsers()}catch(error){toast(error.message)}}}
function bindCommon(){document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{category=b.dataset.cat;render()});document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>openAdd(b.dataset.product));document.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>{predominant=b.dataset.method;render()});document.getElementById('clear-cart')?.addEventListener('click',()=>{cart=[];render()});document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{let i=Number(b.dataset.qty);cart[i].qty+=Number(b.dataset.delta);if(cart[i].qty<1)cart.splice(i,1);render()});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.remove),1);render()});document.querySelectorAll('.item-method').forEach(s=>s.onchange=()=>{const i=cart[Number(s.dataset.index)];i.method=s.value;i.price=s.value==='QR'?i.product.qr:i.product.cash;render()});document.getElementById('confirm-sale')?.addEventListener('click',saleConfirm);document.querySelectorAll('#open-scanner').forEach(b=>b.onclick=openScanner);document.querySelectorAll('[data-scan-ticket]').forEach(b=>b.onclick=()=>showScannerModal(b.dataset.scanTicket));document.querySelectorAll('[data-restock-bar]').forEach(b=>b.onclick=()=>newRestock(b.dataset.restockBar));document.getElementById('stock-adjust')?.addEventListener('click',openAdjustment);document.getElementById('new-restock')?.addEventListener('click',()=>newRestock());document.querySelectorAll('[data-send]').forEach(b=>b.onclick=()=>advanceRequest(b.dataset.send,'ENVIADA'));document.querySelectorAll('[data-receive]').forEach(b=>b.onclick=()=>advanceRequest(b.dataset.receive,'RECIBIDA'));document.getElementById('invite-user')?.addEventListener('click',()=>userForm());document.getElementById('retry-users')?.addEventListener('click',loadUsers);document.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>userForm(usersCache.find(u=>u.id===b.dataset.editUser)));if(page==='users'&&!usersLoaded&&!usersLoading&&!usersError)loadUsers();if(page==='sales')bindSales();if(page==='products')bindProducts();if(page==='stock'){document.getElementById('stock-search').oninput=e=>{const q=e.target.value.toLowerCase();document.getElementById('stock-body').innerHTML=stockRows(db.products.filter(p=>p.name.toLowerCase().includes(q)))}}}
function render(){if(!canAccessPage(page))page='dashboard';if(page==='users'&&window.yambaAuth?.profile?.role!=='ADMIN')page='dashboard';const html=page==='dashboard'?dashboard():page==='pos'?posPage():page==='sales'?salesPage():page==='tickets'?ticketsPage():page==='bars'?barsPage():page==='stock'?stockPage():page==='products'?productsPage():page==='warehouse'?warehousePage():page==='users'?usersPage():restockPage();shell(html,page==='pos'?'pos':'');bindCommon()}
render();
